"""WHOT-ML Paper 1 — Kaggle Cloud Execution Entrypoint.

CRITICAL ARCHITECTURAL BOUNDARY:
This script MUST ONLY execute inside Kaggle Cloud containers.
Attempting to run this script in the local development environment (e.g. Windows)
will IMMEDIATELY fail-closed with exit code 1.
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import io
import json
import os
import subprocess
import sys
import tarfile
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List


def assert_kaggle_environment() -> None:
    """Mandatory runtime guard: production execution is ONLY permitted inside Kaggle Cloud."""
    is_kaggle = (
        (Path("/kaggle/working").exists() or "KAGGLE_KERNEL_RUN_TYPE" in os.environ)
        and sys.platform != "win32"
    )
    if not is_kaggle:
        print("\n" + "!" * 80)
        print("PRODUCTION EXECUTION REFUSED.")
        print("This is the local development environment.")
        print("The Paper 1 production suite must execute inside Kaggle Cloud.")
        print("Use the Kaggle dispatch mechanism instead:")
        print("    python experiments/paper1/kaggle/dispatch_production.py")
        print("No production experiments were started.")
        print("!" * 80 + "\n")
        sys.exit(1)


# Enforce boundary immediately on module load
assert_kaggle_environment()

PAYLOAD_B64 = ""


def unpack_payload(dest_dir: Path) -> None:
    """Unpack embedded experiment code and configs into working directory."""
    raw = base64.b64decode(PAYLOAD_B64.encode("ascii"))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
        tar.extractall(dest_dir)
    print(f"[KAGGLE BOOTSTRAP] Unpacked experiment apparatus into {dest_dir}")


def bootstrap_project_whot(dest_dir: Path) -> Path:
    """Clone Project-WHOT from GitHub and checkout frozen commit 7c1a2dc."""
    repo_dir = dest_dir / "Project-WHOT"
    if not repo_dir.exists():
        print("[KAGGLE BOOTSTRAP] Cloning Project-WHOT from GitHub (https://github.com/Brayan114/Project-WHOT.git)...")
        subprocess.run(
            ["git", "clone", "https://github.com/Brayan114/Project-WHOT.git", str(repo_dir)],
            check=True,
        )

    expected_commit = "7c1a2dc23a277fdfb5e9052d4d90e3798fb24ea4"
    print(f"[KAGGLE BOOTSTRAP] Checking out frozen commit {expected_commit}...")
    subprocess.run(["git", "-C", str(repo_dir), "fetch", "--all", "--tags"], check=True)
    subprocess.run(["git", "-C", str(repo_dir), "checkout", expected_commit], check=True)

    actual_commit = subprocess.check_output(
        ["git", "-C", str(repo_dir), "rev-parse", "HEAD"], text=True
    ).strip()

    if actual_commit != expected_commit:
        raise RuntimeError(f"Commit SHA mismatch: expected {expected_commit}, got {actual_commit}")

    diff = subprocess.check_output(
        ["git", "-C", str(repo_dir), "diff", expected_commit, "--", "whot_ml/"], text=True
    ).strip()
    if diff:
        raise RuntimeError(f"whot_ml/ modified in cloned repository: {diff}")

    print(f"[KAGGLE BOOTSTRAP] Verified frozen commit {actual_commit[:7]} (whot_ml/ 100% clean)")
    return repo_dir


def main() -> None:
    parser = argparse.ArgumentParser(description="WHOT-ML Paper 1 Kaggle Cloud Entrypoint")
    parser.add_argument("--mode", choices=["dry-run", "production"], default="dry-run")
    parser.add_argument("--confirm-production", action="store_true")
    args = parser.parse_args()

    if args.mode == "production" and not args.confirm_production:
        print("ERROR: --mode production requires --confirm-production")
        sys.exit(1)

    is_dry_run = (args.mode == "dry-run")
    work_dir = Path("/kaggle/working")
    os.chdir(work_dir)

    print("=" * 80)
    print(f"WHOT-ML PAPER 1 — KAGGLE CLOUD EXECUTION")
    print(f"Mode: {args.mode.upper()} (is_dry_run={is_dry_run})")
    print(f"Working Directory: {work_dir}")
    print("=" * 80)

    # 1. Unpack code payload
    unpack_payload(work_dir)

    # 2. Clone and checkout Project-WHOT at frozen commit
    repo_dir = bootstrap_project_whot(work_dir)

    # 3. Configure sys.path and environment
    if str(repo_dir) not in sys.path:
        sys.path.insert(0, str(repo_dir))
    if str(work_dir) not in sys.path:
        sys.path.insert(0, str(work_dir))

    os.environ["WHOT_ROOT"] = str(work_dir)
    os.environ["WHOT_RUN_DIR"] = str(work_dir)

    # 4. Verify simulator constants
    from whot_ml.version import BASELINE_ENVIRONMENT, FROZEN_BASELINE, SIMULATOR_VERSION
    if SIMULATOR_VERSION != "1.0.0" or BASELINE_ENVIRONMENT != "WHOT-NG-v1.0" or not FROZEN_BASELINE:
        raise RuntimeError("Simulator constants invalid!")

    # 5. Run freeze verification test (run from repo_dir so git operates on Project-WHOT)
    print("\n[KAGGLE BOOTSTRAP] Running freeze verification test suite...")
    subprocess.run(
        [sys.executable, "-m", "pytest", str(work_dir / "tests/test_simulator_freeze.py")],
        cwd=str(repo_dir),
        check=True,
    )

    # 6. Import experiment runners
    from experiments.paper1.scripts.common import (
        ExperimentPaths,
        FROZEN_SIMULATOR_COMMIT,
        compute_config_hash,
    )
    from experiments.paper1.scripts.generate_plots import generate_all_plots
    from experiments.paper1.scripts.generate_tables import generate_all_tables
    from experiments.paper1.scripts.run_exp01 import run_exp01
    from experiments.paper1.scripts.run_exp02 import run_exp02
    from experiments.paper1.scripts.run_exp03 import run_exp03
    from experiments.paper1.scripts.run_exp04 import run_exp04
    from experiments.paper1.scripts.run_exp05 import build_variant_config, run_exp05
    from experiments.paper1.scripts.run_exp06 import run_exp06
    from whot_ml.ruleset import get_baseline_config

    run_timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    prefix = "dryrun" if is_dry_run else "production"
    run_id = f"paper1_{prefix}_{run_timestamp}_{FROZEN_SIMULATOR_COMMIT}"

    # Route outputs into /kaggle/working
    ExperimentPaths.set_run_directory(work_dir)

    # Compute config hashes
    base_cfg = get_baseline_config()
    cfg_hashes = {
        "baseline_whot_ng_v1": compute_config_hash(base_cfg),
        "var_no_stack_2": compute_config_hash(build_variant_config({"pick_two_stacking": "NO_STACKING"})),
        "var_no_stack_3": compute_config_hash(build_variant_config({"pick_three_stacking": "NO_STACKING"})),
        "var_no_decl": compute_config_hash(build_variant_config({"last_card_declaration_enabled": False})),
        "var_penalty_2": compute_config_hash(build_variant_config({"last_card_violation_penalty": "DRAW_2"})),
    }

    scheduled_count = 55 if is_dry_run else 12350
    print(f"\n[KAGGLE EXECUTION] Starting {scheduled_count} {args.mode} runs...")
    start_time = time.time()
    exp_results: Dict[str, Any] = {}

    print(">>> Executing EXP-01...")
    exp_results["EXP-01"] = run_exp01(pilot=False, dry_run=is_dry_run)

    print(">>> Executing EXP-02...")
    exp_results["EXP-02"] = run_exp02(pilot=False, dry_run=is_dry_run)

    print(">>> Executing EXP-03...")
    exp_results["EXP-03"] = run_exp03(pilot=False, dry_run=is_dry_run)

    print(">>> Executing EXP-04...")
    exp_results["EXP-04"] = run_exp04(pilot=False, dry_run=is_dry_run)

    print(">>> Executing EXP-05...")
    exp_results["EXP-05"] = run_exp05(pilot=False, dry_run=is_dry_run)

    print(">>> Executing EXP-06...")
    exp_results["EXP-06"] = run_exp06(pilot=False, dry_run=is_dry_run)

    # Presentation Tier
    suffix = "dry_run" if is_dry_run else "full"
    print(f"\n>>> Generating Tables (suffix={suffix})...")
    generate_all_tables(pilot=False, suffix=suffix)

    print(f"\n>>> Generating Figures (suffix={suffix})...")
    generate_all_plots(pilot=False, suffix=suffix)

    # Packaging
    archive_name = f"whot_ml_{prefix}_artifacts.tar.gz"
    archive_path = work_dir / archive_name
    print(f"\n[KAGGLE PACKAGING] Creating {archive_name}...")
    with tarfile.open(archive_path, "w:gz") as tar:
        for folder in ["raw", "processed", "figures", "tables"]:
            fp = work_dir / folder
            if fp.exists():
                tar.add(fp, arcname=folder)

    with open(archive_path, "rb") as f:
        archive_sha = hashlib.sha256(f.read()).hexdigest()

    # Manifest
    elapsed_total = round(time.time() - start_time, 2)
    manifest_data = {
        "run_id": run_id,
        "is_dry_run": is_dry_run,
        "mode": args.mode,
        "source_repository": "Brayan114/Project-WHOT",
        "source_revision": FROZEN_SIMULATOR_COMMIT,
        "simulator_version": SIMULATOR_VERSION,
        "baseline_environment": BASELINE_ENVIRONMENT,
        "execution_environment": "KAGGLE_CLOUD_CPU",
        "configuration_hashes": cfg_hashes,
        "total_runtime_seconds": elapsed_total,
        "total_runtime_minutes": round(elapsed_total / 60, 2),
        "artifact_archive": archive_name,
        "artifact_archive_sha256": archive_sha,
        "status": "SUCCESS",
    }

    manifest_file = work_dir / f"{prefix}_manifest.json"
    with open(manifest_file, "w", encoding="utf-8") as f:
        json.dump(manifest_data, f, indent=2)

    print("=" * 80)
    print(f"KAGGLE EXECUTION COMPLETE: SUCCESS")
    print(f"Manifest: {manifest_file}")
    print(f"Archive: {archive_path} ({archive_path.stat().st_size:,} bytes)")
    print(f"Total Runtime: {elapsed_total}s ({elapsed_total / 60:.2f} min)")
    print("=" * 80)


if __name__ == "__main__":
    main()
